// INDIA. Departments: income tax (returns, advance tax, audit reports), TDS/TCS, GST, payroll (PF, ESI,
// profession tax) and company-law filings (MCA). The financial year is 1 April to 31 March for everyone.
// Read on 2026-11-10/11 on incometax.gov.in, the Income Tax Department's Act and Rules pages, the GST Council's
// site and PIB. The MCA, EPFO, ESIC and State tax sites refused automated access, so everything that cites them
// carries verified: false and is shown to the person as "confirm on the official source".
//
// Two income-tax laws run side by side in 2026-27: the Income-tax Act, 1961 (old form numbers) for income of
// FY 2025-26, and the Income-tax Act, 2025 (new form numbers) for FY 2026-27. Each filing names both forms.
import type { Compliance, Cond, CountryPack, DueRule } from '../types.ts';
import { C, afterFY, afterFYDays, afterFYx, afterPeriod, all, any, choice, etag, event, fixed, is, kind, no, not, opts, src, stag, yes, yn } from '../dsl.ts';
import { IN_STATES } from './geo.ts';

const ITD = 'Income Tax Department', GST = 'GST (CBIC and State tax departments)', MCA = 'Ministry of Corporate Affairs', D = '2026-11-11';
const G20 = ['AR', 'ML', 'PY', 'SK', 'TS', 'UK'], G10 = ['MN', 'MZ', 'NL', 'TR'];           // goods-only registration limit below Rs 40 lakh
const COMP75 = ['AR', 'MN', 'ML', 'MZ', 'NL', 'SK', 'TR', 'UK'];                          // composition limit Rs 75 lakh
const Q22 = ['CG', 'MP', 'GJ', 'MH', 'KA', 'GA', 'KL', 'TN', 'TS', 'AP', 'DH', 'PY', 'AN', 'LD'];   // quarterly GSTR-3B due the 22nd (others the 24th)
const PT = ['AP', 'AS', 'BR', 'CG', 'GJ', 'JH', 'KA', 'KL', 'MP', 'MH', 'MN', 'ML', 'MZ', 'NL', 'OD', 'PB', 'SK', 'TN', 'TS', 'TR', 'WB', 'PY'];   // profession tax (not read on an official page)

const PERSON = kind('individual', 'sole_prop');
const CO = kind('corporation');
const FIRM = kind('partnership', 'llc');
const NP = kind('nonprofit');
const BIZ = any(kind('sole_prop', 'partnership', 'llc', 'corporation'), yes('in_business'));     // carries on a business or profession
const ORG = any(BIZ, NP);                                                                          // anyone who may deduct tax, register for GST or employ
const PERSON_BIZ = any(kind('sole_prop'), all(kind('individual'), yes('in_business')));
const TAX_AUDIT = any(is('in_turnover', 't3'), all(is('in_turnover', 't2'), yes('in_cash5')), yes('in_prof_50'));
const AUDITED = any(TAX_AUDIT, yes('in_audit_other'));
const TP = yes('in_tp');
const DEDUCTOR = any(yes('in_employees'), yes('in_tds_other'), yes('in_tds_nr'), yes('in_tcs'));
const GST_ON = any(yes('in_gst_reg'), yes('in_gst_over'), yes('in_gst_special'));
const REGULAR = any(is('in_gst_scheme', 'regular_m'), is('in_gst_scheme', 'regular_q'));
const EXT26 = { 2026: '2026-11-21' };                                                              // CBDT Circular 07/2026: audit-case returns for FY 2025-26

const LATE_FEE = 'Late fee of Rs 5,000 (Rs 1,000 if total income is up to Rs 5 lakh), plus interest on unpaid tax.';
const GST_FEE = 'Late fee of Rs 100 a day under CGST and the same under State GST, with lower caps for small taxpayers, plus interest on tax paid late.';

/** One income-tax return, in up to three timings: no audit, audit, transfer pricing. */
function itr(id: string, form: string, who: Cond, what: string, timings: ('plain' | 'audit' | 'tp')[], plainDue: [DueRule, string], audited: Cond): Compliance[] {
  const base = { form, dept: 'income', head: 'Income tax', authority: ITD, weight: 100, frequency: 'annual' as const, penalty: LATE_FEE, source: 's263', verified: true };
  const out: Compliance[] = [];
  if (timings.includes('plain')) out.push(C(id, { ...base, name: `Income-tax return (${what})`, brief: `The yearly return of income for ${what}, for the financial year ended 31 March.`, why: 'You have income to report and your accounts do not need an audit.', applies: all(who, not(audited), not(TP)), due: plainDue[0], dueText: plainDue[1] }));
  if (timings.includes('audit')) out.push(C(id + '_audit', { ...base, name: `Income-tax return (${what}, audit case)`, brief: `The yearly return of income for ${what} whose accounts must be audited, and for every company.`, why: 'Your accounts must be audited, or you are a company.', applies: all(who, audited, not(TP)), due: afterFYx(7, EXT26), dueText: '31 October of the year after the financial year. For FY 2025-26 the CBDT extended this date to 21 November 2026.' }));
  if (timings.includes('tp')) out.push(C(id + '_tp', { ...base, name: `Income-tax return (${what}, transfer pricing case)`, brief: `The yearly return of income for ${what} that must also furnish a transfer pricing report.`, why: 'You had international or specified domestic transactions, so a transfer pricing report is required.', applies: all(who, TP), due: afterFY(8), dueText: '30 November of the year after the financial year. The 2026 extension for audit cases does not apply to this date.' }));
  return out;
}

